"""Main screen, as recorded in "StockPilot catalog search" (generated by Vortex; vortex-appium-python v1)."""

from appium.webdriver.common.appiumby import AppiumBy

from .base_page import BasePage


class MainPage(BasePage):
    SEARCH_PRODUCTS = (AppiumBy.ID, "home-search-bar")
    SEARCH_PRODUCTS_BRANDS_SKU = (AppiumBy.ID, "catalog-search-input")
    DAILY_DEW_PURE_COW = (AppiumBy.ID, "product-card-SKU-10065-open")
    SKU_SKU_10065_EAN = (AppiumBy.ID, "product-sku")
    WRITE_REVIEW = (AppiumBy.ANDROID_UIAUTOMATOR, "new UiSelector().text(\"Write a review\")")

    def tap_search_products(self, fallback=None, check_first=True):
        self.tap(self.SEARCH_PRODUCTS, fallback, check_first)

    def fill_search_products_brands_sku(self, value):
        self.fill(self.SEARCH_PRODUCTS_BRANDS_SKU, value)

    def tap_daily_dew_pure_cow(self, fallback=None, check_first=True):
        self.tap(self.DAILY_DEW_PURE_COW, fallback, check_first)

    def scroll_to_write_review(self, max_swipes=None, **options):
        return self.scroll_into_view(self.WRITE_REVIEW, max_swipes, **options)
